<?php
require '../config/config.php'; role(['administrator','pustakawan']);
$id=(int)($_GET['id']??0); if(!$id) die('Anggota tidak ditemukan.');
$q=$pdo->prepare("SELECT id,name,username,class_name,status FROM users WHERE id=? AND role='anggota'");$q->execute([$id]);$member=$q->fetch();if(!$member) die('Anggota tidak ditemukan.');
$v=$pdo->prepare("SELECT visit_date,visit_time FROM visits WHERE user_id=? ORDER BY visit_date DESC,visit_time DESC LIMIT 100");$v->execute([$id]);$visits=$v->fetchAll();
$l=$pdo->prepare("SELECT l.loan_date,l.due_date,l.returned_at,l.late_days,l.fine,b.title,c.code FROM loans l JOIN copies c ON c.id=l.copy_id JOIN books b ON b.id=c.book_id WHERE l.user_id=? ORDER BY l.loan_date DESC,l.id DESC LIMIT 100");$l->execute([$id]);$loans=$l->fetchAll();
$total=count($visits)+count($loans);$active=count(array_filter($loans,fn($x)=>$x['returned_at']===null));
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Aktivitas Anggota</title><link rel=stylesheet href="../public/style.css"></head><body><div class="layout"><?php include '../public/nav.php';?><main class="main"><h1>👤 Detail Aktivitas Anggota</h1><div class="card" style="margin-bottom:16px"><h2 style="margin-top:0"><?=e($member['name'])?></h2><p><?=e($member['username'])?> · Kelas <?=e($member['class_name']??'-')?> · Status <?=e($member['status'])?></p><div class="cards"><div><small>Total aktivitas</small><div class="num"><?=$total?></div></div><div><small>Kunjungan</small><div class="num"><?=count($visits)?></div></div><div><small>Peminjaman</small><div class="num"><?=count($loans)?></div></div><div><small>Pinjaman aktif</small><div class="num"><?=$active?></div></div></div></div><div class="grid"><div class="card"><h3>🚶 Riwayat Kunjungan</h3><table class="table"><tr><th>Tanggal</th><th>Jam</th></tr><?php foreach($visits as $x):?><tr><td><?=e($x['visit_date'])?></td><td><?=e($x['visit_time'])?></td></tr><?php endforeach?><?php if(!$visits):?><tr><td colspan="2">Belum ada kunjungan.</td></tr><?php endif?></table></div><div class="card"><h3>🔄 Riwayat Peminjaman</h3><table class="table"><tr><th>Buku</th><th>Jatuh Tempo</th><th>Status</th></tr><?php foreach($loans as $x):?><tr><td><?=e($x['title'])?><br><small><?=e($x['code'])?></small></td><td><?=e($x['due_date'])?></td><td><?=$x['returned_at']?'Selesai':'Aktif'?></td></tr><?php endforeach?><?php if(!$loans):?><tr><td colspan="3">Belum ada peminjaman.</td></tr><?php endif?></table></div></div></main></div></body></html>